using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.VertexAlgebra.Lattice;

internal sealed class LatticeRelativeBRSTCohomologyDocument : IScribeDocumentDefinition
{
    private const string Prefix = "D5/S3/VertexAlgebra/Lattice/LatticeRelativeBRSTCohomology.";
    private static DocumentBlock Node(string name, string prose, DescribeRole role = DescribeRole.Theorem) =>
        Describe.Lean(DescribeId.Create("latticerelativebrstcohomology-" + name.Replace(".", "-").Replace("_", "-").ToLowerInvariant()),
            DeclarationHandle.Create(Prefix + name[(name.LastIndexOf('.') + 1)..]), H(name), StatementSource.WithoutFormula(),
            AssessedProvenance.FromRepo(), Blocks(Paragraph(Text(prose))), role);

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original relative BRST cohomology and exact transverse representatives",
        H("Original relative BRST cohomology and exact transverse representatives"), Blocks(
            Paragraph(Text("The state space is the original all-charge lattice carrier tensor the original occupation bc Fock space. The relative shell is fixedMomentum(p) intersect ker(b(0)) intersect ker(matterMode(0)+ghostVirasoro(0)), with unshifted total energy. Its differential is the restriction of the original totalCharge, whose invariance follows from the native Ward and covariance identities. The remainder is exactly Q-d0, including the chargeEnergy(p)c(0) contribution.")),
            Paragraph(Text("Let N=massShellCutoff(D,p)=(1-chargeEnergy(D,p)).toNat. For every lattice rank, integral momentum p including zero, null frame F, arbitrary finite complex transverse basis B, and matrix H satisfying H*gramComplex(D)=gramComplex(D)*H=1, actual h(Q-d0) preserves this shell. Induction on k shows that every nonzero actualBasis coefficient after k steps has original filtration degree at least -N+k. The accepted shell coefficient theorem simultaneously bounds that degree above by N. At k=2N+1 no coefficient survives. No finite-basis choice, real transverse basis or positivity of a Gram form enters this argument.")),
            Paragraph(Text("The actual signed ghost-number operator preserves all three shell constraints. Its commutators with delta and h have degrees +1 and -1, so it commutes with h*delta, delta*h and their finite inverse polynomials. On the literal b(0) kernel, a zero-quartet-count occupation has only the {1} sector: the possible {1,3} coefficient is killed by b(0). Consequently N*P0=P0 and P0*N=P0 on this shell. Corrected inclusion has ghost number one, and projection after N equals projection. Applying delta to corrected inclusion has ghost number two; projection would also give ghost number one. Over Complex the equality of the output with twice itself forces actual transferred differential zero, for every rank and momentum.")),
            Paragraph(Text("For cohomology require additionally rank(D)=26 and pPlus(F,p) nonzero. The native total-square anomaly gives Q squared zero. The actual quartet maps satisfy the unperturbed contraction, and native FinitePerturbation.Input.finite_perturbation applies at the proved exponent. Its corrected inclusion I, projection P and homotopy Hcorr give every original cycle x the decomposition x=I(P(x))+Q(Hcorr(x)). Actual image-Q boundaries are exactly the kernel of corrected projection on cycles. Mathlib's first isomorphism theorem therefore identifies the genuine cycles/image-Q quotient with the transverse ground target.")),
            Paragraph(Text("The polynomial target is defined independently by coefficients: each nonzero coefficient at exponent nu obeys weight(nu)+chargeEnergy(D,p)=1, where weight sums multiplicity times the positive oscillator frequency r+1. The original groundMap is injective on all polynomials, and maps this exact-energy submodule exactly to the shell intersect ker(M). Restriction to its image supplies the final polynomial coordinates. Corrected representatives have actual ghost number one and are unique modulo actual Q boundaries. A cycle of integer ghost number q different from one has an explicit primitive of ghost number q-1; at ghost number one the correction primitive has number zero.")),
            Paragraph(Text("The contraction and cohomology statements retain nonzero pPlus. All-charge nilpotence and zero transfer do not establish a contraction at p=0 or pPlus=0. These are algebraic statements about the specified original BRST model; they do not assert the full no-ghost theorem, Monster moonshine, a complete VOA/CFT or AdS/CFT construction, or new literature results.")),
            Paragraph(Text("The source escape audit remains unfinished at https://github.com/the-omega-institute/trureturing/issues/25942. Compilation of these algebraic results does not complete that registration.")),
            Node("h_full_remainder_nilpotent_on_relativeMassShell", "The actual ambient word h*(totalCharge-d0), iterated exactly 2*massShellCutoff(D,p)+1 times, vanishes on every vector of the literal original relative shell. The all-powers degree induction and shell preservation prove uniform nilpotence without a nilpotence hypothesis."),
            Node("Number.shellQ", "The original totalCharge restricted using totalCharge_mem_relativeMassShell, with both inverse-Gram equations. No replacement or zero-mode-corrected differential is used.", DescribeRole.Definition),
            Node("Number.shellN", "The original signed occupation ghost-number operator restricted to the literal shell by its proved invariance.", DescribeRole.Definition),
            Node("Cohomology", "The complex vector space of actual original-Q cycles modulo the actual image of original Q, with rank 26 providing the image-to-kernel map.", DescribeRole.Definition),
            Node("cohomologyEquivEnergy", "For every original lattice of rank 26, null frame F, arbitrary finite complex transverse basis B, two-sided inverse Gram matrix H, and momentum p with pPlus(F,p) nonzero, a complex-linear equivalence from the original cycles/image-Q quotient to the independently defined exact-energy transverse polynomial submodule.", DescribeRole.Definition),
            Node("off_charge_one_exact", "Under rank 26, both inverse-Gram equations and nonzero pPlus, every original-Q cycle x with actual ghost number q different from one equals Q(Hcorr(x)); the displayed primitive has actual ghost number q-1."),
            Node("exact_energy_representative", "Under the same cohomology hypotheses, every original-Q cycle has a unique exact-energy transverse polynomial coordinate whose corrected representative differs from it by an actual original-Q boundary and has actual ghost number one. If the cycle itself has ghost number one, the constructed primitive has ghost number zero."))));
}
